import math

def get_prime_factorization(n):
    factors = {}
    d = 2
    temp = n
    while d * d <= temp:
        while temp % d == 0:
            factors[d] = factors.get(d, 0) + 1
            temp //= d
        d += 1
    if temp > 1:
        factors[temp] = factors.get(temp, 0) + 1
    return factors

def tau_n_to_the_12(n):
    if n == 1:
        return 1

    factors = get_prime_factorization(n)

    # tau(n^12) = product((12 * a_i + 1))
    tau_val = 1
    for exponent in factors.values():
        tau_val *= (12 * exponent + 1)
    return tau_val

def check_n_equals_tau_n_to_the_12(n):
    if n <= 0:
        return False

    tau_val = tau_n_to_the_12(n)
    return n == tau_val

# Part 1: Check n=1
