def prime_factorization(n):
    factors = {}
    d = 2
    temp = n
    while d * d <= temp:
        while temp % d == 0:
            factors[d] = factors.get(d, 0) + 1
            temp //= d
        d += 1
    if temp > 1:
        factors[temp] = factors.get(temp, 0) + 1
    return factors

def tau_n_pow_12(n_factors):
    # n = p1^a1 * p2^a2 * ...
    # n^12 = p1^(12*a1) * p2^(12*a2) * ...
    # tau(n^12) = (12*a1 + 1) * (12*a2 + 1) * ...
    tau = 1
    for exponent in n_factors.values():
        tau *= (12 * exponent + 1)
    return tau

solutions = []
# Check n=1 separately
solutions.append((1, True))

# Brute force search for odd n > 1 up to 300
# We only need to check odd numbers since n must be odd.
for n in range(3, 301, 2):
    factors = prime_factorization(n)
    tau_val = tau_n_pow_12(factors)
    if n == tau_val:
        solutions.append((n, True))

print("Solutions found for n <= 300:")
for n, is_sol in solutions:
    print(f"n={n}, is_solution={is_sol}")
